// 로직이 UI에 묶여있어서 재사용 불가
function Toggle() {
  const [on, setOn] = useState(false);
  return (
    <button
      style={{ background: on ? 'blue' : 'gray' }}  // 이 스타일이 싫으면?
      onClick={() => setOn(!on)}
    >
      {on ? 'ON' : 'OFF'}
    </button>
  );
}

