// 로직만 분리 (커스텀 훅)
function useToggle(initial = false) {
  const [on, setOn] = useState(initial);
  const toggle = () => setOn(prev => !prev);
  const setOn_ = () => setOn(true);
  const setOff = () => setOn(false);
  return { on, toggle, setOn: setOn_, setOff };
}

// UI는 사용자가 자유롭게
function MyToggle() {
  const { on, toggle } = useToggle();
  return (
    <button
      className={on ? 'my-on-style' : 'my-off-style'}
      onClick={toggle}
    >
      {on ? '켜짐' : '꺼짐'}
    </button>
  );
}

function AnotherToggle() {
  const { on, toggle } = useToggle();
  return <Switch checked={on} onCheckedChange={toggle} />  // 다른 UI
}

